    /// </summary>
    [pbr::OriginalName("CCAI_SERVICE_TYPE_ONDEWO_NLU_QA")] OndewoNluQa = 10,
    /// <summary>
    /// ONDEWO NLU Webhook
    /// Enables webhook-based event integration for NLU events and external notifications.
