    [pbr::OriginalName("CCAI_SERVICE_TYPE_ONDEWO_NLU_LLM_RAG")] OndewoNluLlmRag = 20,
    /// <summary>
    /// ONDEWO Analytics
    /// Provides comprehensive analytics and metrics for call center operations and KPI tracking.
